using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.UI;using RoadGunner;using RoadGunner.Editor;
public static class ConceptBaselineCapture {
 static async Task Wait(float secs){float end=Time.realtimeSinceStartup+secs;while(Time.realtimeSinceStartup<end)await Task.Delay(30);}
 public static async Task<string> Main(string target){if(!EditorApplication.isPlaying)throw new Exception("Play required");Application.runInBackground=true;PrototypeBuilder.SetPortraitGameView(540,960);EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor")).Focus();var s=UnityEngine.Object.FindAnyObjectByType<GameSession>();s.Restart();s.health.DamageEnabled=false;s.turret.enabled=false;s.spawns.enabled=false;foreach(var r in s.spawns.authoredRaiders){if(r.agent.enabled&&r.agent.isOnNavMesh)r.agent.isStopped=true;r.enabled=false;}var axis=Quaternion.Euler(0,45,0);Vector2 p=target=="workshop"?new Vector2(12,-15):target=="camp"?new Vector2(27.5f,27):target=="salvage"?new Vector2(-19,52):target=="raider"?new Vector2(-22,-16):target=="gate"?new Vector2(0,61):target=="veteran"?new Vector2(41,58):new Vector2(0,22);s.vehicle.ResetPose(axis*new Vector3(p.x*2.5f,.7f,p.y*2.5f),axis);s.vehicle.Body.constraints=RigidbodyConstraints.FreezeAll;s.follow.Snap();if(target=="workshop"){s.health.DamageEnabled=true;s.health.Damage(65,false);}await Wait(.35f);Canvas.ForceUpdateCanvases();string path="/Users/arthuri/Documents/Codex/2026-10-09/macbook-app-store/work/concept-overhaul-2026-10-16/before-"+target+".png";var source=s.follow.GetComponent<Camera>();var go=new GameObject("Temporary portrait capture");var camera=go.AddComponent<Camera>();camera.CopyFrom(source);camera.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);camera.enabled=false;camera.aspect=540f/960;var data=camera.GetUniversalAdditionalCameraData();data.renderPostProcessing=source.GetUniversalAdditionalCameraData().renderPostProcessing;data.renderShadows=true;var rt=new RenderTexture(540,960,24);rt.Create();camera.targetTexture=rt;var canvas=s.hud.GetComponentInParent<Canvas>();var mode=canvas.renderMode;var previousCamera=canvas.worldCamera;float distance=canvas.planeDistance;var active=RenderTexture.active;
