 finally{canvas.renderMode=mode;canvas.worldCamera=previousCamera;canvas.planeDistance=distance;RenderTexture.active=active;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(go);Canvas.ForceUpdateCanvases();}}
